"""Keep the CI-only base/dev/build lock tied to its pyproject inputs."""

from __future__ import annotations

import argparse
import hashlib
import re
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
INPUT = ROOT / "ci/requirements.in"
LOCK = ROOT / "ci/requirements.txt"


def expected_input() -> str:
    project = tomllib.loads((ROOT / "pyproject.toml").read_text())
    return "\n".join(
        [
            "# Generated by scripts/ci_dependencies.py --write-input; do not edit.",
            "# CI only: Linux CPython 3.11 and 3.12; no backend extras.",
            f"# requires-python: {project['project']['requires-python']}",
            f"# build-backend: {project['build-system']['build-backend']}",
            *project["project"]["dependencies"],
            *project["project"]["optional-dependencies"]["dev"],
            *project["build-system"]["requires"],
            "",
        ]
    )


def check_lock(body: str) -> None:
    """Reject options, URLs, unpinned entries, missing hashes and broken syntax."""
    entries = body.replace("\\\n", " ").splitlines()
    names: set[str] = set()
    pins: set[str] = set()
    for entry in entries:
        if not entry.strip() or entry.startswith("#"):
            continue
        match = re.fullmatch(
            r"([a-z0-9][a-z0-9_.-]*==[a-zA-Z0-9_.+!-]+)" r"(?:\s+--hash=sha256:[0-9a-f]{64})+\s*",
            entry,
        )
        if match is None:
            raise ValueError(f"Malformed hash-locked requirement: {entry[:100]}")
        pin = match[1]
        name = re.sub(r"[-_.]+", "-", pin.split("==")[0])
        if name in names:
            raise ValueError(f"Duplicate lock requirement: {name}")
        names.add(name)
        pins.add(pin)
    if not names:
        raise ValueError("Empty dependency lock")
    for requirement in expected_input().splitlines():
        if "==" in requirement and requirement not in pins:
            raise ValueError(f"Missing required exact pin: {requirement}")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--write-input", action="store_true")
    mode.add_argument("--stamp-lock", action="store_true")
    args = parser.parse_args()
    expected = expected_input()
    if args.write_input:
        INPUT.parent.mkdir(exist_ok=True)
        INPUT.write_text(expected)
        return
    if INPUT.read_text() != expected:
        raise ValueError("CI dependency inputs are stale; regenerate ci/requirements.in and lock")
    stamp = f"# input-sha256: {hashlib.sha256(expected.encode()).hexdigest()}\n"
    lock = LOCK.read_text()
    if args.stamp_lock:
        check_lock(lock)
        LOCK.write_text(stamp + lock)
    else:
        if not lock.startswith(stamp):
            raise ValueError("CI dependency lock is stale; regenerate and stamp it")
        check_lock(lock)
    print("CI dependency inputs and hash lock are valid")


if __name__ == "__main__":
    main()
